37	           MISO : out  STD_LOGIC;
38	           MOSI : in  STD_LOGIC;
39	           CS : in  STD_LOGIC;
40				  BUF_OUT : out STD_LOGIC_VECTOR (W-1 downto 0) := (others => '0');
41				  BUF_IN : in STD_LOGIC_VECTOR (W-1 downto 0);
42	           CLK : in  STD_LOGIC;
43				  COMPLETE : out STD_LOGIC;
44				  -- processing the complete word after it is complete leaves very little time
45				  -- for read operations. Indicate when the first PREWIDTH bits are ready which
46				  -- allows more time to prepare the response to the next word
47				  PRE_COMPLETE : out STD_LOGIC;
48				  PRE_BUF_OUT : out STD_LOGIC_VECTOR (PREWIDTH-1 downto 0) := (others => '0')
49					);
50	end spi_slave;
51	
52	architecture Behavioral of spi_slave is
53		signal miso_buffer : STD_LOGIC_VECTOR (W-1 downto 0);
54		signal mosi_buffer : STD_LOGIC_VECTOR (W-2 downto 0);
55	
56		signal data_valid : STD_LOGIC_VECTOR(2 downto 0);
57		signal data_synced : STD_LOGIC_VECTOR(2 downto 0);
58		signal data : STD_LOGIC_VECTOR(W-1 downto 0);
59		signal pre_data : STD_LOGIC_VECTOR(PREWIDTH-1 downto 0);
60		signal pre_data_valid : STD_LOGIC_VECTOR(3 downto 0);
61		
62		signal bit_cnt : integer range 0 to W-1;
63	begin
64	
65		process(CLK)
66		begin
67			if rising_edge(CLK) then
68				COMPLETE <= '0';
69				PRE_COMPLETE <= '0';
70				data_valid(2 downto 1) <= data_valid(1 downto 0);
71				pre_data_valid(3 downto 1) <= pre_data_valid(2 downto 0);
72				if data_valid(2) = '1' then
73					if data_synced(0) = '0' then
74						BUF_OUT <= data;
75						COMPLETE <= '1';
76						data_synced(0) <= '1';
77					end if;
78				else
79					data_synced(0) <= '0';
80				end if;
81				if pre_data_valid(3 downto 2) = "01" then
82					-- pre_data has just become valid
83					PRE_BUF_OUT <= pre_data;
84					PRE_COMPLETE <= '1';
85				end if;
86			end if;
87		end process;
88	
89		MISO <= BUF_IN(15) when bit_cnt = 0 else miso_buffer(W-2);
90	
91		slave_in: process(SPI_CLK, CS)
92		begin
93			if CS = '1' then
94				bit_cnt <= 0;
95				data_valid(0) <= '0';
96				pre_data_valid(0) <= '0';
97			elsif rising_edge(SPI_CLK) then
98				-- data input process: sample on the rising edge
99				data_synced(2 downto 1) <= data_synced(1 downto 0);
100				if bit_cnt = PREWIDTH-1 then
101					-- first couple of bits are ready
102					pre_data <= mosi_buffer(PREWIDTH-2 downto 0) & MOSI;
103					pre_data_valid(0) <= '1';
104				end if;
105				if bit_cnt = W-1 then
106					-- this was the last bit
107					pre_data_valid(0) <= '0';
108					data_valid(0) <= '1';
109					data <= mosi_buffer(W-2 downto 0) & MOSI;
110				else
111					if data_valid(0) = '1' and data_synced(2) = '1' then
112						data_valid(0) <= '0';
113					end if;
114					mosi_buffer <= mosi_buffer(W-3 downto 0) & MOSI;
115				end if;
116				
117				-- data output process: data should be launched on the falling edge
118				-- but the delay is too large. Launch on the rising edge instead
119				if bit_cnt < W-1 then
120					bit_cnt <= bit_cnt + 1;
121					if bit_cnt = 0 then
122						miso_buffer <= BUF_IN;
123					else
124						miso_buffer <= miso_buffer(W-2 downto 0) & '0';
125					end if;
126				else
127					bit_cnt <= 0;
128				end if;
129			end if;
130		end process;
131		
