19	----------------------------------------------------------------------------------
20	library IEEE;
21	use IEEE.STD_LOGIC_1164.ALL;
22	
23	-- Uncomment the following library declaration if using
24	-- arithmetic functions with Signed or Unsigned values
25	use IEEE.NUMERIC_STD.ALL;
26	
27	-- Uncomment the following library declaration if instantiating
28	-- any Xilinx primitives in this code.
29	--library UNISIM;
30	--use UNISIM.VComponents.all;
31	
32	entity SPICommands is
33	    Port ( CLK : in  STD_LOGIC;
34	           RESET : in  STD_LOGIC;
35	           SCLK : in  STD_LOGIC;
36	           MOSI : in  STD_LOGIC;
37	           MISO : out  STD_LOGIC;
38	           NSS : in  STD_LOGIC;
39	           NEW_SAMPLING_DATA : in  STD_LOGIC;
40	           SAMPLING_RESULT : in  STD_LOGIC_VECTOR (303 downto 0);
41				  ADC_MINMAX : in STD_LOGIC_VECTOR(95 downto 0);
42	           SOURCE_UNLOCKED : in  STD_LOGIC;
43	           LO_UNLOCKED : in  STD_LOGIC;
44	           MAX2871_DEF_4 : out  STD_LOGIC_VECTOR (31 downto 0);
45	           MAX2871_DEF_3 : out  STD_LOGIC_VECTOR (31 downto 0);
46	           MAX2871_DEF_1 : out  STD_LOGIC_VECTOR (31 downto 0);
47	           MAX2871_DEF_0 : out  STD_LOGIC_VECTOR (31 downto 0);
48	           SWEEP_DATA : out  STD_LOGIC_VECTOR (95 downto 0);
49	           SWEEP_ADDRESS : out  STD_LOGIC_VECTOR (12 downto 0);
50	           SWEEP_WRITE : out  STD_LOGIC_VECTOR (0 downto 0);
51	           SWEEP_POINTS : out  STD_LOGIC_VECTOR (12 downto 0);
52	           NSAMPLES : out  STD_LOGIC_VECTOR (12 downto 0);
53				  STAGES : out STD_LOGIC_VECTOR (2 downto 0);
54				  SETTLING_TIME : out STD_LOGIC_VECTOR (19 downto 0);
55				  SYNC_ENABLED : out STD_LOGIC;
56				  SYNC_MASTER : out STD_LOGIC;
57				  PORT1_STAGE : out STD_LOGIC_VECTOR (2 downto 0);
58				  PORT2_STAGE : out STD_LOGIC_VECTOR (2 downto 0);
59				  PORT1_EN : out STD_LOGIC;
60				  PORT2_EN : out STD_LOGIC;
61				  REF_EN : out STD_LOGIC;
62				  AMP_SHDN : out STD_LOGIC;
63				  SOURCE_RF_EN : out STD_LOGIC;
64				  LO_RF_EN : out STD_LOGIC;
65				  SOURCE_CE_EN : out STD_LOGIC;
66				  LO_CE_EN : out STD_LOGIC;
67				  PORTSWITCH_EN : out STD_LOGIC;
68				  LEDS : out STD_LOGIC_VECTOR(2 downto 0);
69				  WINDOW_SETTING : out STD_LOGIC_VECTOR(1 downto 0);
70				  ADC_PRESCALER : out STD_LOGIC_VECTOR(7 downto 0);
71				  ADC_PHASEINC : out STD_LOGIC_VECTOR(11 downto 0);
72				  INTERRUPT_ASSERTED : out STD_LOGIC;
73				  RESET_MINMAX : out STD_LOGIC;
74				  SWEEP_HALTED : in STD_LOGIC;
75				  SWEEP_RESUME : out STD_LOGIC;
76				  
77				  -- hardware overwrite signals
78				  SPI_OVERWRITE_ENABLED : out STD_LOGIC;
79				  SPI_OVERWRITE_DATA : out STD_LOGIC_VECTOR(14 downto 0);
80				  
81				  -- DFT signals
82				  DFT_BIN1_PHASEINC : out  STD_LOGIC_VECTOR (15 downto 0);
83	           DFT_DIFFBIN_PHASEINC : out  STD_LOGIC_VECTOR (15 downto 0);
84				  DFT_RESULT_READY : in  STD_LOGIC;
85	           DFT_OUTPUT : in  STD_LOGIC_VECTOR (191 downto 0);
86	           DFT_NEXT_OUTPUT : out  STD_LOGIC;
87				  DFT_ENABLE : out STD_LOGIC;
88				  			  
89				  DEBUG_STATUS : in STD_LOGIC_VECTOR(10 downto 0));
90	end SPICommands;
91	
92	architecture Behavioral of SPICommands is
93		COMPONENT spi_slave
94		Generic(W : integer;
95				  PREWIDTH : integer);
96		PORT(
97			SPI_CLK : in  STD_LOGIC;
98			MISO : out  STD_LOGIC;
99			MOSI : in  STD_LOGIC;
100			CS : in  STD_LOGIC;
101			BUF_OUT : out STD_LOGIC_VECTOR (W-1 downto 0) := (others => '0');
102			BUF_IN : in STD_LOGIC_VECTOR (W-1 downto 0);
103			CLK : in  STD_LOGIC;
104			COMPLETE : out STD_LOGIC;
105			PRE_COMPLETE : out STD_LOGIC;
106			PRE_BUF_OUT : out STD_LOGIC_VECTOR (PREWIDTH-1 downto 0)
107		);
108		END COMPONENT;
109		
110		-- SPI control signals
111		signal spi_buf_out : std_logic_vector(15 downto 0);
112		signal spi_buf_in : std_logic_vector(15 downto 0);
113		signal spi_complete : std_logic;
114		signal spi_pre_complete : std_logic;
115		signal spi_pre_buf_out : std_logic_vector(2 downto 0);
116		signal word_cnt : integer range 0 to 19;
117		type SPI_states is (FirstWord, WriteSweepConfig, ReadResult, WriteRegister);
118		signal state : SPI_states;
119		signal selected_register : integer range 0 to 31;
120		
121		signal dft_next : std_logic;
122		
123		signal last_NSS : std_logic;
124		
125		signal sweep_config_write : std_logic;
126		signal unread_sampling_data : std_logic;
127		signal data_overrun : std_logic;
128		-- Configuration registers
129		signal interrupt_mask : std_logic_vector(15 downto 0);
130		signal interrupt_status : std_logic_vector(15 downto 0);
131		
132		signal latched_result : std_logic_vector(287 downto 0);
133		signal sweepconfig_buffer : std_logic_vector(79 downto 0);
134	begin
135		SPI: spi_slave
136		GENERIC MAP(W => 16,
137						PREWIDTH => 3)
138		PORT MAP(
139			SPI_CLK => SCLK,
140			MISO => MISO,
141			MOSI => MOSI,
142			CS => NSS,
143			BUF_OUT => spi_buf_out,
144			BUF_IN => spi_buf_in,
145			CLK => CLK,
146			COMPLETE => spi_complete,
147			PRE_COMPLETE => spi_pre_complete,
148			PRE_BUF_OUT => spi_pre_buf_out
149		);
150		
151		SWEEP_WRITE(0) <= sweep_config_write;
152		DFT_NEXT_OUTPUT <= dft_next;
153		DFT_ENABLE <= interrupt_mask(5); 
154	
155		process(CLK, RESET)
156		begin
157			if rising_edge(CLK) then
158				if RESET = '1' then
159					sweep_config_write <= '0';
160					data_overrun <= '0';
161					SWEEP_POINTS <= (others => '0');
162					NSAMPLES <= (others => '0');
163					--SETTLING_TIME <= (others => '0');
164					PORT1_EN <= '0';
165					PORT2_EN <= '0';
166					REF_EN <= '0';
167					AMP_SHDN <= '1';
168					SOURCE_RF_EN <= '0';
169					LO_RF_EN <= '0';
170					SOURCE_CE_EN <= '0';
171					LO_CE_EN <= '0';
172					PORTSWITCH_EN <= '0';
173					LEDS <= (others => '1');
174					WINDOW_SETTING <= "00";
175					unread_sampling_data <= '0';
176					interrupt_mask <= (others => '0');
177					ADC_PRESCALER <= std_logic_vector(to_unsigned(112, 8));
178					ADC_PHASEINC <= std_logic_vector(to_unsigned(1120, 12));
179					RESET_MINMAX <= '0';
180					INTERRUPT_ASSERTED <= '0';
181					latched_result <= (others => '0');
182					
183					SPI_OVERWRITE_ENABLED <= '0';
184					SPI_OVERWRITE_DATA <= (others => '0');
185					
186					DFT_BIN1_PHASEINC <= (others => '0');
187					DFT_DIFFBIN_PHASEINC <= (others => '0');
188					dft_next <= '0';
189					last_NSS <= '1';
190				else
191					interrupt_status <= DEBUG_STATUS(10 downto 1) & DFT_RESULT_READY & SWEEP_HALTED & data_overrun & unread_sampling_data & SOURCE_UNLOCKED & LO_UNLOCKED;
192					if (interrupt_status and interrupt_mask) = "0000000000000000" then
193						INTERRUPT_ASSERTED <= '0';
194					else
195						INTERRUPT_ASSERTED <= '1';
196					end if;
197					if sweep_config_write = '1' then
198						sweep_config_write <= '0';
199					end if;
200					if dft_next = '1' then
201						dft_next <= '0';
202					end if;
203					RESET_MINMAX <= '0';
204					SWEEP_RESUME <= '0';
205					if NEW_SAMPLING_DATA = '1' then
206						unread_sampling_data <= '1';
207						if unread_sampling_data = '1' then
208							data_overrun <= '1';
209						end if;
210					end if;
211					last_NSS <= NSS;
212					if NSS = '0' and last_NSS = '1' then
213						word_cnt <= 0;
214						spi_buf_in <= interrupt_status;
215						state <= FirstWord;
216					else
217						-- handle read operations when the first PREWIDTH bits are complete
218						if spi_pre_complete = '1' then
219						case state is
220						when FirstWord =>
221							-- initial word determines the action
222							case spi_pre_buf_out is
223									when "010" => state <= FirstWord;
224													spi_buf_in <= "1111000010100101";							
225									when "101" => state <= ReadResult;-- can use same state as read result, but the latched data will contain the DFT values
226													latched_result(175 downto 0) <= DFT_OUTPUT(191 downto 16);
227													spi_buf_in <= DFT_OUTPUT(15 downto 0);
228													dft_next <= '1';
229									when "110" => state <= ReadResult;
230													latched_result <= SAMPLING_RESULT(303 downto 16);
231													spi_buf_in <= SAMPLING_RESULT(15 downto 0);
232													unread_sampling_data <= '0';
233									when "111" => state <= ReadResult; -- can use same state as read result, but the latched data will contain the min/max ADC values
234													latched_result(79 downto 0) <= ADC_MINMAX(95 downto 16);
235													spi_buf_in <= ADC_MINMAX(15 downto 0);
236									--ignore other options
237									when others =>
238							end case;
239							when ReadResult =>
240								-- pass on next word of latched result
241								spi_buf_in <= latched_result(15 downto 0);
242								latched_result <= "0000000000000000" & latched_result(287 downto 16);
243							when others =>
244						end case;
245						end if;
246						-- handle write operations when the whole word is complete
247						if spi_complete = '1' then
248							word_cnt <= word_cnt + 1;
249							case state is
250							when FirstWord =>
251								-- initial word determines action
252								case spi_buf_out(15 downto 13) is
253									when "000" => state <= WriteSweepConfig;
254													-- also extract the point number
255													SWEEP_ADDRESS <= spi_buf_out(12 downto 0);
256									when "001" => state <= FirstWord;
257													SWEEP_RESUME <= '1';
258									when "011" => state <= FirstWord;
259													RESET_MINMAX <= '1';
260									when "100" => state <= WriteRegister;
261													selected_register <= to_integer(unsigned(spi_buf_out(4 downto 0)));
262									-- ignore read options (already handled in other state machine)
263									when "010" =>
264									when "101" =>
265									when "110" =>
266									when "111" =>
267									when others => state <= FirstWord;
268								end case;
269							when WriteRegister =>
270								-- write received data into previously selected register
271								case selected_register is
272									when 0 => interrupt_mask <= spi_buf_out;
273									when 1 => SWEEP_POINTS <= spi_buf_out(12 downto 0);
274									when 2 => NSAMPLES <= spi_buf_out(12 downto 0);
275									when 3 => PORTSWITCH_EN <= spi_buf_out(0);
276												PORT1_EN <= spi_buf_out(15);
277												PORT2_EN <= spi_buf_out(14);
278												REF_EN <= spi_buf_out(13);
279												AMP_SHDN <= not spi_buf_out(12);
280												SOURCE_RF_EN <= spi_buf_out(11);
281												LO_RF_EN <= spi_buf_out(10);
282												LEDS <= not spi_buf_out(9 downto 7);
283												WINDOW_SETTING <= spi_buf_out(6 downto 5);
284												SOURCE_CE_EN <= spi_buf_out(4);
285												LO_CE_EN <= spi_buf_out(3);
286												SYNC_MASTER <= spi_buf_out(1);
