288									when 5 => ADC_PHASEINC <= spi_buf_out(11 downto 0);
289									when 6 => STAGES <= spi_buf_out(15 downto 13);
290												SYNC_ENABLED <= spi_buf_out(12);
291												PORT1_STAGE <= spi_buf_out(5 downto 3);
292												PORT2_STAGE <= spi_buf_out(2 downto 0);
293									when 7 => SPI_OVERWRITE_ENABLED <= spi_buf_out(15);
294												SPI_OVERWRITE_DATA <= spi_buf_out(14 downto 0);
295									when 8 => MAX2871_DEF_0(15 downto 0) <= spi_buf_out;
296									when 9 => MAX2871_DEF_0(31 downto 16) <= spi_buf_out;
297									when 10 => MAX2871_DEF_1(15 downto 0) <= spi_buf_out;
298									when 11 => MAX2871_DEF_1(31 downto 16) <= spi_buf_out;
299									when 12 => MAX2871_DEF_3(15 downto 0) <= spi_buf_out;
300									when 13 => MAX2871_DEF_3(31 downto 16) <= spi_buf_out;
301									when 14 => MAX2871_DEF_4(15 downto 0) <= spi_buf_out;
302									when 15 => MAX2871_DEF_4(31 downto 16) <= spi_buf_out;
