304									when 19 => DFT_DIFFBIN_PHASEINC <= spi_buf_out;
305									when 20 => SETTLING_TIME(15 downto 0) <= spi_buf_out;
306									when 21 => SETTLING_TIME(19 downto 16) <= spi_buf_out(3 downto 0);
307									when others => 
308								end case;
309								selected_register <= selected_register + 1;
310							when WriteSweepConfig =>
311								if word_cnt = 6 then
312									-- Sweep config data is complete pass on
313									SWEEP_DATA <= sweepconfig_buffer & spi_buf_out;
314									sweep_config_write <= '1';
315								else
316									-- shift next word into buffer
317									sweepconfig_buffer <= sweepconfig_buffer(63 downto 0) & spi_buf_out;
318								end if;
319							-- read already handled in pre_complete, ignore
