21	static void SwitchBytes(uint16_t &value) {
22		value = (value & 0xFF00) >> 8 | (value & 0x00FF) << 8;
23	}
24	static void SwitchBytes(int16_t &value) {
25		value = (value & 0xFF00) >> 8 | (value & 0x00FF) << 8;
26	}
