28	void FPGA::WriteRegister(FPGA::Reg reg, uint16_t value) {
29		uint8_t cmd[4] = {0x80, (uint8_t) reg, (uint8_t) (value >> 8), (uint8_t) (value & 0xFF)};
30		Low(CS);
31		HAL_SPI_Transmit(&FPGA_SPI, (uint8_t*) cmd, 4, 100);
32		High(CS);
33		if(reg == Reg::ADCPrescaler) {
34			ADC_samplerate = Clockrate / value;
35		}
36	}
