38	bool FPGA::Configure(uint32_t start_address, uint32_t bitstream_size) {
39		if(!PROGRAM_B.gpio) {
40			LOG_WARN("PROGRAM_B not defined, assuming FPGA configures itself in master configuration");
41			// wait too allow enough time for FPGA configuration
42			HAL_Delay(2000);
43			return true;
44		}
45		LOG_INFO("Loading bitstream of size %lu...", bitstream_size);
46		Low(PROGRAM_B);
47		while(isHigh(INIT_B));
48		High(PROGRAM_B);
49		while(!isHigh(INIT_B));
50	
51		if(isHigh(DONE)) {
52			LOG_ERR("DONE not asserted, aborting configuration");
53			return false;
54		}
55	
56		uint32_t lastmessage = HAL_GetTick();
57		uint8_t buf[256];
58		while(bitstream_size > 0) {
59			if(HAL_GetTick() - lastmessage > 100) {
60				LOG_DEBUG("Remaining: %lu", bitstream_size);
61				lastmessage = HAL_GetTick();
62			}
63			uint16_t size = sizeof(buf);
64			if(size > bitstream_size) {
65				size = bitstream_size;
66			}
67			// TODO this part might be doable with the DMA instead of the buffer
68			// get chunk of bitstream from flash...
69			HWHAL::flash.read(start_address, size, buf);
70			// ... and pass it on to FPGA
71			HAL_SPI_Transmit(&CONFIGURATION_SPI, buf, size, 100);
72			bitstream_size -= size;
73			start_address += size;
74		}
75		Delay::ms(1);
76		if(!isHigh(INIT_B)) {
77			LOG_CRIT("INIT_B asserted after configuration, CRC error occurred");
78			return false;
79		}
80		if(!isHigh(DONE)) {
81			LOG_CRIT("DONE still low after configuration");
82			return false;
83		}
84		LOG_INFO("...configured");
85		return true;
86	}
87	
88	bool FPGA::Init(HaltedCallback cb) {
89		halted_cb = cb;
90		busy_reading = false;
91		SysCtrlReg = 0;
92		ISRMaskReg = 0;
93		// Reset FPGA
94		High(FPGA_RESET);
95		SetMode(Mode::FPGA);
96		AbortSweep();
97		Delay::us(1);
98		Low(FPGA_RESET);
99		Delay::ms(10);
100	
101		// Check if FPGA response is as expected
102		uint8_t cmd[4] = {0x40, 0x00, 0x00, 0x00};
103		uint8_t recv[4];
104		Low(CS);
105		HAL_SPI_TransmitReceive(&FPGA_SPI, (uint8_t*) cmd, (uint8_t*) recv, 4, 100);
106		High(CS);
107	
108		uint16_t resp = (uint16_t) recv[2] << 8 | recv[3];
109		uint16_t status = (uint16_t) recv[0] << 8 | recv[1];
110		if(resp != 0xF0A5) {
111			LOG_ERR("Initialization failed, got 0x%04x instead of 0xF0A5", resp);
112			return false;
113		}
114	
115		LOG_DEBUG("Initialized, status register: 0x%04x", status);
116		return true;
117	}
118	
119	void FPGA::SetNumberOfPoints(uint16_t npoints) {
120		// register has to be set to number of points - 1
121		npoints--;
122		WriteRegister(Reg::SweepPoints, npoints);
123	}
124	
125	void FPGA::SetSamplesPerPoint(uint32_t nsamples) {
126		// register is in multiples of 16
127		nsamples /= 16;
128		// constrain to maximum value
129		if(nsamples >= 8192) {
130			nsamples = 8191;
131		}
132		WriteRegister(Reg::SamplesPerPoint, nsamples);
133	}
134	
135	void FPGA::SetSettlingTime(uint16_t us) {
136		// register is in multiples of 1/102.4 MHz
137		uint32_t value = (uint32_t) us * 512 / 5;
138		constexpr uint32_t maxval = 0xFFFFF;
139		if(value > maxval) {
140			value = maxval;
141		}
142		WriteRegister(Reg::SettlingTimeLow, value & 0xFFFF);
143		WriteRegister(Reg::SettlingTimeHigh, value >> 16);
144	}
145	
146	void FPGA::SetupSweep(uint8_t stages, uint8_t port1_stage, uint8_t port2_stage, bool synchronize, bool syncMaster) {
147		uint16_t value = 0x0000;
148		value |= (uint16_t) (stages & 0x07) << 13;
149		if(synchronize) {
150			value |= 0x1000;
151		}
152		value |= (port1_stage & 0x07) << 3;
153		value |= (port2_stage & 0x07) << 0;
154		WriteRegister(Reg::SweepSetup, value);
155		Enable(Periphery::SyncMaster, syncMaster);
156	}
157	
158	void FPGA::Enable(Periphery p, bool enable) {
159		if (enable) {
160			SysCtrlReg |= (uint16_t) p;
161			WriteRegister(Reg::SystemControl, SysCtrlReg);
162		} else {
163			Disable(p);
164		}
165	}
166	
167	void FPGA::Disable(Periphery p) {
168		SysCtrlReg &= ~(uint16_t) p;
169		WriteRegister(Reg::SystemControl, SysCtrlReg);
170	}
171	
172	bool FPGA::IsEnabled(Periphery p) {
173		if(SysCtrlReg & (uint16_t) p) {
174			return true;
175		} else {
176			return false;
177		}
178	}
179	
180	void FPGA::SetWindow(Window w) {
181		SysCtrlReg &= ~0x0060;
182		SysCtrlReg |= (int) w << 5;
183		WriteRegister(Reg::SystemControl, SysCtrlReg);
184	}
185	
186	void FPGA::EnableInterrupt(Interrupt i) {
187		ISRMaskReg |= (uint16_t) i;
188		WriteRegister(Reg::InterruptMask, ISRMaskReg);
189	}
190	
191	void FPGA::DisableInterrupt(Interrupt i) {
192		ISRMaskReg &= ~(uint16_t) i;
193		WriteRegister(Reg::InterruptMask, ISRMaskReg);
194	}
195	
196	void FPGA::DisableAllInterrupts() {
197		ISRMaskReg = 0x0000;
198		WriteRegister(Reg::InterruptMask, ISRMaskReg);
199	}
