201	void FPGA::WriteMAX2871Default(uint32_t *DefaultRegs) {
202		WriteRegister(Reg::MAX2871Def0LSB, DefaultRegs[0] & 0xFFFF);
203		WriteRegister(Reg::MAX2871Def0MSB, DefaultRegs[0] >> 16);
204		WriteRegister(Reg::MAX2871Def1LSB, DefaultRegs[1] & 0xFFFF);
205		WriteRegister(Reg::MAX2871Def1MSB, DefaultRegs[1] >> 16);
206		WriteRegister(Reg::MAX2871Def3LSB, DefaultRegs[3] & 0xFFFF);
207		WriteRegister(Reg::MAX2871Def3MSB, DefaultRegs[3] >> 16);
208		WriteRegister(Reg::MAX2871Def4LSB, DefaultRegs[4] & 0xFFFF);
209		WriteRegister(Reg::MAX2871Def4MSB, DefaultRegs[4] >> 16);
210	}
211	
212	void FPGA::WriteSweepConfig(uint16_t pointnum, bool lowband, uint32_t *SourceRegs, uint32_t *LORegs,
213			uint8_t attenuation, uint64_t frequency, Samples samples, bool halt, LowpassFilter filter) {
214		uint16_t send[7];
215		// select which point this sweep config is for
216		send[0] = pointnum & 0x1FFF;
217		// assemble sweep config from required fields of PLL registers
218		uint16_t LO_N = (LORegs[0] & 0x7FFF8000) >> 15;
219		uint16_t LO_FRAC = (LORegs[0] & 0x00007FF8) >> 3;
220		uint16_t LO_M = (LORegs[1] & 0x00007FF8) >> 3;
221		uint16_t LO_VCO = (LORegs[3] & 0xFC000000) >> 26;
222		uint16_t LO_DIV_A = (LORegs[4] & 0x00700000) >> 20;
223	
224		uint16_t Source_N = (SourceRegs[0] & 0x7FFF8000) >> 15;
225		uint16_t Source_FRAC = (SourceRegs[0] & 0x00007FF8) >> 3;
226		uint16_t Source_M = (SourceRegs[1] & 0x00007FF8) >> 3;
227		uint16_t Source_VCO = (SourceRegs[3] & 0xFC000000) >> 26;
228		uint16_t Source_DIV_A = (SourceRegs[4] & 0x00700000) >> 20;
229	
230		uint16_t Source_Power = (SourceRegs[4] & 0x00000018) >> 3;
231	
232		send[1] = LO_M >> 4;
233		if (halt) {
234			send[1] |= 0x8000;
235		}
236		if(LO_N & 0x40) {
237			send[1] |= 0x4000;
238		}
239		if(Source_N & 0x40) {
240			send[1] |= 0x2000;
241		}
242		send[1] |= (int) samples << 10;
243		if(filter == LowpassFilter::Auto) {
244			// Select source LP filter
245			if (frequency >= 3500000000) {
246				send[1] |= (int) LowpassFilter::None << 8;
247			} else if (frequency >= 1800000000) {
248				send[1] |= (int) LowpassFilter::M3500 << 8;
249			} else if (frequency >= 900000000) {
250				send[1] |= (int) LowpassFilter::M1880 << 8;
251			} else {
252				send[1] |= (int) LowpassFilter::M947 << 8;
253			}
254		} else {
255			send[1] |= (int) filter << 8;
256		}
257		send[2] = (LO_M & 0x000F) << 12 | LO_FRAC;
258		send[3] = LO_DIV_A << 13 | LO_VCO << 7 | (LO_N & 0x3F) << 1;
259		if (lowband) {
260			send[3] |= 0x0001;
261		}
262		send[4] = Source_Power << 14 | (uint16_t) attenuation << 7 | Source_M >> 5;
263		send[5] = (Source_M & 0x001F) << 11 | Source_FRAC >> 1;
264		send[6] = (Source_FRAC & 0x0001) << 15 | Source_DIV_A << 12 | Source_VCO << 6 | (Source_N & 0x3F);
265		SwitchBytes(send[0]);
266		SwitchBytes(send[1]);
267		SwitchBytes(send[2]);
268		SwitchBytes(send[3]);
269		SwitchBytes(send[4]);
270		SwitchBytes(send[5]);
271		SwitchBytes(send[6]);
272		Low(CS);
273		HAL_SPI_Transmit(&FPGA_SPI, (uint8_t*) send, 14, 100);
274		High(CS);
275	}
276	
277	static inline int64_t sign_extend_64(int64_t x, uint16_t bits) {
278		int64_t m = 1ULL << (bits - 1);
279		return (x ^ m) - m;
280	}
281	
282	static FPGA::ReadCallback callback;
283	static uint8_t raw[40];
284	static FPGA::SamplingResult result;
285	
286	bool FPGA::InitiateSampleRead(ReadCallback cb) {
287		if(busy_reading) {
288			LOG_ERR("ISR while SPI is busy");
289			return false;
290		}
291		callback = cb;
292		static uint8_t cmd[40] = {0xC0, 0x00};
293		// Start data read
294		if(HAL_SPI_GetState(&FPGA_SPI) != HAL_SPI_STATE_READY) {
295			LOG_WARN("SPI abort: %d", HAL_SPI_GetState(&FPGA_SPI));
296			HAL_SPI_Abort(&FPGA_SPI);
297		}
298		Low(CS);
299		busy_reading = true;
300		if(HAL_SPI_TransmitReceive_DMA(&FPGA_SPI, cmd, raw, 40) != HAL_OK) {
301			LOG_ERR("Failed to start SPI DMA");
302			busy_reading = false;
303		}
304		return true;
305	}
306	
307	static int64_t assembleSampleResultValue(uint8_t *raw) {
308	//	LOG_DEBUG("Raw: 0x%02x 0x%02x 0x%02x 0x%02x 0x%02x 0x%02x", raw[4], raw[5], raw[2], raw[3], raw[1], raw[0]);
309		return sign_extend_64(
310				(uint16_t) raw[0] << 8 | raw[1] | (uint32_t) raw[2] << 24
311						| (uint32_t) raw[3] << 16 | (uint64_t) raw[4] << 40
312						| (uint64_t) raw[5] << 32, 48);
313	}
314	
315	extern "C" {
316	void HAL_SPI_TxRxCpltCallback(SPI_HandleTypeDef *hspi) {
317		uint16_t status = (uint16_t) raw[0] << 8 | raw[1];
318		// Assemble data from words
319		result.P1I = assembleSampleResultValue(&raw[32]);
320		result.P1Q = assembleSampleResultValue(&raw[26]);
321		result.P2I = assembleSampleResultValue(&raw[20]);
322		result.P2Q = assembleSampleResultValue(&raw[14]);
323		result.RefI = assembleSampleResultValue(&raw[8]);
324		result.RefQ = assembleSampleResultValue(&raw[2]);
325		result.pointNum = (uint16_t)(raw[38]&0x1F) << 8 | raw[39];
326		result.stageNum = (raw[38] & 0xE0) >> 5;
327		High(CS);
328		busy_reading = false;
329		if ((status & 0x0004) && callback) {
330			callback(result);
331		}
332		if ((status & 0x0010) && halted_cb) {
333			halted_cb();
334		}
335	}
336	}
